import{_ as o,C as e,c as i,o as d,a3 as s,G as t,w as n}from"./chunks/framework.Dk6sf0Ip.js";const q=JSON.parse('{"title":"Paso a Paso: Salida de Cubiertas del Stock","description":"","frontmatter":{},"headers":[],"relativePath":"CasosParticulares/cubiertas/remitosalidacubiertas.md","filePath":"CasosParticulares/cubiertas/remitosalidacubiertas.md","lastUpdated":1759345498000}'),c={name:"CasosParticulares/cubiertas/remitosalidacubiertas.md"};function u(g,a,h,m,p,b){const r=e("lite-youtube"),l=e("ClientOnly");return d(),i("div",null,[a[0]||(a[0]=s('<h1 id="paso-a-paso-salida-de-cubiertas-del-stock" tabindex="-1">Paso a Paso: Salida de Cubiertas del Stock <a class="header-anchor" href="#paso-a-paso-salida-de-cubiertas-del-stock" aria-label="Permalink to &quot;Paso a Paso: Salida de Cubiertas del Stock&quot;">​</a></h1><p>Este es el proceso para registrar la salida de cubiertas desde el sistema, generando un <strong>Remito de Salida</strong> y actualizando el stock de forma automática.</p><h2 id="_1-iniciar-el-remito-de-salida-pantalla-principal" tabindex="-1">1. Iniciar el Remito de Salida (Pantalla Principal) <a class="header-anchor" href="#_1-iniciar-el-remito-de-salida-pantalla-principal" aria-label="Permalink to &quot;1. Iniciar el Remito de Salida (Pantalla Principal)&quot;">​</a></h2><p>Se encuentra en <strong><em>ALMACEN/STOCK</em></strong> dentro de la opción <strong>&quot;Remito salida&quot;</strong>.</p><h3 id="_15-4-01-remito-total-resta-stock" tabindex="-1">15.4.01 Remito total (Resta Stock) <a class="header-anchor" href="#_15-4-01-remito-total-resta-stock" aria-label="Permalink to &quot;15.4.01 Remito total (Resta Stock)&quot;">​</a></h3><h4 id="_1-revisar-completar-encabezado" tabindex="-1"><strong>1. Revisar/Completar Encabezado:</strong> <a class="header-anchor" href="#_1-revisar-completar-encabezado" aria-label="Permalink to &quot;**1. Revisar/Completar Encabezado:**&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Nombre</th><th>Qué ingresar</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Número del remito, generado automáticamente por el sistema.</td></tr><tr><td><code>Fecha</code></td><td>Fecha en la que se realiza la salida.</td></tr><tr><td><code>Referencia</code></td><td>Motivo de la salida (ej: <strong>ENTREGA A CLIENTE</strong>, <strong>ENVÍO A SERVICIO</strong>, etc.).</td></tr><tr><td><code>Cliente</code></td><td>Selecciona el cliente destino de la cubierta (ej: <strong>Don Andres</strong>).</td></tr><tr><td><code>Responsable</code></td><td>Persona a cargo de la entrega.</td></tr><tr><td><code>Opcional</code></td><td>Adjuntar archivo (ej: comprobante de entrega o documento de soporte).</td></tr></tbody></table><h4 id="_2-ir-al-detalle" tabindex="-1">2. <strong>Ir al Detalle:</strong> <a class="header-anchor" href="#_2-ir-al-detalle" aria-label="Permalink to &quot;2. **Ir al Detalle:**&quot;">​</a></h4><p>En la sección <strong>Detalle</strong>, haz clic en el botón azul <strong>AGREGAR</strong> ubicado en la parte inferior izquierda.</p><hr><h2 id="_2-agregar-la-actividad-detalle-de-la-salida" tabindex="-1">2. Agregar la Actividad (Detalle de la Salida) <a class="header-anchor" href="#_2-agregar-la-actividad-detalle-de-la-salida" aria-label="Permalink to &quot;2. Agregar la Actividad (Detalle de la Salida)&quot;">​</a></h2><p>Al hacer clic en <strong>AGREGAR</strong>, se abrirá la ventana <strong>&quot;Agregar actividad&quot;</strong>.</p><h4 id="_1-buscar-seleccionar-el-articulo-cubierta" tabindex="-1">1. <strong>Buscar/Seleccionar el Artículo (Cubierta):</strong> <a class="header-anchor" href="#_1-buscar-seleccionar-el-articulo-cubierta" aria-label="Permalink to &quot;1. **Buscar/Seleccionar el Artículo (Cubierta):**&quot;">​</a></h4><ul><li>En el campo <strong>&quot;Artículo Depósito Id&quot;</strong>, escribe el código o la descripción de la cubierta a retirar.</li><li>El sistema pedirá un mínimo de <strong>2 caracteres</strong> para habilitar el filtrado.</li><li><strong>Selecciona la cubierta</strong> desde la lista que aparece.</li></ul><h4 id="_2-seleccionar-el-deposito-de-salida" tabindex="-1">2. <strong>Seleccionar el Depósito de Salida:</strong> <a class="header-anchor" href="#_2-seleccionar-el-deposito-de-salida" aria-label="Permalink to &quot;2. **Seleccionar el Depósito de Salida:**&quot;">​</a></h4><ul><li>A la derecha del campo, el sistema mostrará el depósito de origen.</li><li><strong>Asegúrate de elegir el depósito &quot;CUBIERTAS&quot;</strong> (o el que corresponda).</li></ul><h4 id="_3-cantidad-a-retirar" tabindex="-1">3. <strong>Cantidad a Retirar:</strong> <a class="header-anchor" href="#_3-cantidad-a-retirar" aria-label="Permalink to &quot;3. **Cantidad a Retirar:**&quot;">​</a></h4><ul><li>En el campo de cantidad, indica el número de cubiertas que van a salir del stock.</li></ul><hr><h2 id="_3-finalizar-la-salida-del-detalle" tabindex="-1">3. Finalizar la Salida del Detalle <a class="header-anchor" href="#_3-finalizar-la-salida-del-detalle" aria-label="Permalink to &quot;3. Finalizar la Salida del Detalle&quot;">​</a></h2><h4 id="_1-guardar-el-detalle" tabindex="-1">1. <strong>Guardar el Detalle:</strong> <a class="header-anchor" href="#_1-guardar-el-detalle" aria-label="Permalink to &quot;1. **Guardar el Detalle:**&quot;">​</a></h4><ul><li>Haz clic en el botón azul <strong>GUARDAR</strong> en la ventana &quot;Agregar actividad&quot;.</li><li>Esto cargará la línea de salida en el detalle del remito principal.</li></ul><h4 id="_2-agregar-mas-articulos" tabindex="-1">2. <strong>Agregar Más Artículos:</strong> <a class="header-anchor" href="#_2-agregar-mas-articulos" aria-label="Permalink to &quot;2. **Agregar Más Artículos:**&quot;">​</a></h4><ul><li>Si el remito incluye más cubiertas, repite el <strong>Paso 2</strong>.</li></ul><h4 id="_3-finalizar-el-remito" tabindex="-1">3. <strong>Finalizar el Remito:</strong> <a class="header-anchor" href="#_3-finalizar-el-remito" aria-label="Permalink to &quot;3. **Finalizar el Remito:**&quot;">​</a></h4><ul><li>Cuando todos los artículos estén cargados, haz clic en el botón azul <strong>GUARDAR</strong> en la parte superior derecha de la pantalla principal del <strong>&quot;Remito salida&quot;</strong>.</li><li>El sistema descontará automáticamente las cantidades del stock del depósito seleccionado.</li></ul><hr><p>👉 De esta manera, queda registrada formalmente la <strong>salida de cubiertas</strong>, asociada al cliente <strong>Don Andres</strong> (o al cliente/proveedor que corresponda).</p><h4 id="_4-video-tutorial" tabindex="-1">4. Video tutorial <a class="header-anchor" href="#_4-video-tutorial" aria-label="Permalink to &quot;4. Video tutorial&quot;">​</a></h4>',29)),t(l,null,{default:n(()=>[t(r,{videoid:"gxXTA1YQkcA",videotitle:"Remito de salida"})]),_:1})])}const A=o(c,[["render",u]]);export{q as __pageData,A as default};
